// EMBER live voice: a real-time spoken conversation with Gemini Live over a WebSocket.
// The microphone streams to Gemini as 16 kHz PCM; Gemini answers in speech (24 kHz PCM) as it thinks, can be
// interrupted mid-sentence, and calls the same browser-side tools as the typed copilot (3D, scenario, what-if...).
// The server only mints a single-use token (api/live.js); the API key never reaches the browser.
// SI disclosure: written with assistance from Claude (Anthropic). Speech generated by Google Gemini (SI).
const WS = 'wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1beta.GenerativeService.BidiGenerateContentConstrained'

function b64FromInt16(i16) {
  const u8 = new Uint8Array(i16.buffer, i16.byteOffset, i16.byteLength); let s = ''
  for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000))
  return btoa(s)
}
function floatFromB64(b64) {
  const bin = atob(b64), n = bin.length >> 1, out = new Float32Array(n)
  for (let i = 0; i < n; i++) { let v = bin.charCodeAt(2 * i) | (bin.charCodeAt(2 * i + 1) << 8); if (v >= 0x8000) v -= 0x10000; out[i] = v / 32768 }
  return out
}
// mic frame (any rate) -> 16 kHz little-endian Int16
function to16kInt16(x, inRate) {
  const ratio = inRate / 16000, n = Math.floor(x.length / ratio), out = new Int16Array(n)
  for (let i = 0; i < n; i++) {
    const a = Math.floor(i * ratio), b = Math.min(x.length, Math.floor((i + 1) * ratio)); let s = 0
    for (let j = a; j < b; j++) s += x[j]
    const v = Math.max(-1, Math.min(1, b > a ? s / (b - a) : x[a] || 0)); out[i] = v < 0 ? v * 0x8000 : v * 0x7fff
  }
  return out
}

// callbacks: onState(s), onUser(chunk), onEmber(chunk), onTurnEnd(), onTool(name, args), onError(msg), onClose(msg)
export async function createLive({ executors, onState, onUser, onEmber, onTurnEnd, onTool, onError, onClose }) {
  const r = await fetch('/api/live', { method: 'POST' })
  const cfg = await r.json().catch(() => ({}))
  if (!r.ok || !cfg.token) throw new Error(cfg.error || 'live session unavailable (' + r.status + ')')

  const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, channelCount: 1 } })
  const inCtx = new (window.AudioContext || window.webkitAudioContext)()
  const outCtx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 })
  try { await inCtx.resume(); await outCtx.resume() } catch {}
  let ws = null, open = false, closed = false, src = null, proc = null, nextAt = 0, playing = new Set(), turnDone = false
  const state = s => onState?.(s)
  const sendJSON = o => { if (ws && ws.readyState === 1) ws.send(JSON.stringify(o)) }

  function stopPlayback() { for (const n of playing) { try { n.stop() } catch {} } playing.clear(); nextAt = 0 }
  function play(b64) {
    const f = floatFromB64(b64); if (!f.length) return
    const buf = outCtx.createBuffer(1, f.length, 24000); buf.copyToChannel(f, 0)
    const node = outCtx.createBufferSource(); node.buffer = buf; node.connect(outCtx.destination)
    const at = Math.max(nextAt, outCtx.currentTime + 0.03); node.start(at); nextAt = at + buf.duration
    playing.add(node); state('speaking')
    node.onended = () => { playing.delete(node); if (!playing.size && turnDone) state('listening') }
  }

  function startMic() {
    src = inCtx.createMediaStreamSource(stream)
    proc = inCtx.createScriptProcessor(4096, 1, 1)
    proc.onaudioprocess = e => { if (open) sendJSON({ realtimeInput: { audio: { data: b64FromInt16(to16kInt16(e.inputBuffer.getChannelData(0), inCtx.sampleRate)), mimeType: 'audio/pcm;rate=16000' } } }) }
    const mute = inCtx.createGain(); mute.gain.value = 0
    src.connect(proc); proc.connect(mute); mute.connect(inCtx.destination)
  }

  async function onToolCall(calls) {
    state('thinking')
    const functionResponses = []
    for (const fc of calls || []) {
      onTool?.(fc.name, fc.args || {})
      let result
      try { result = executors[fc.name] ? await executors[fc.name](fc.args || {}) : { error: 'unknown tool' } } catch (e) { result = { error: String(e.message || e) } }
      functionResponses.push({ id: fc.id, name: fc.name, response: { result } })
    }
    sendJSON({ toolResponse: { functionResponses } })
  }

  async function onMessage(ev) {
    let m; try { m = JSON.parse(typeof ev.data === 'string' ? ev.data : await ev.data.text()) } catch { return }
    if (m.setupComplete) { open = true; startMic(); state('listening'); return }
    if (m.toolCall) { onToolCall(m.toolCall.functionCalls); return }
    if (m.goAway) { onError?.('The live session is about to end; switch Voice off and on to continue.'); return }
    const sc = m.serverContent; if (!sc) return
    if (sc.interrupted) { stopPlayback(); state('hearing') }
    if (sc.inputTranscription?.text) { onUser?.(sc.inputTranscription.text); if (!playing.size) state('hearing') }
    if (sc.outputTranscription?.text) onEmber?.(sc.outputTranscription.text)
    for (const p of sc.modelTurn?.parts || []) if (p.inlineData?.data) { turnDone = false; play(p.inlineData.data) }
    if (sc.turnComplete || sc.generationComplete) { turnDone = true; if (sc.turnComplete) onTurnEnd?.(); if (!playing.size) state('listening') }
  }

  await new Promise((resolve, reject) => {
    ws = new WebSocket(WS + '?access_token=' + encodeURIComponent(cfg.token))
    const t = setTimeout(() => reject(new Error('live session timed out')), 12000)
    ws.onopen = () => { clearTimeout(t); sendJSON({ setup: cfg.setup }); resolve() }
    ws.onerror = () => { clearTimeout(t); reject(new Error('could not connect to Gemini Live')) }
    ws.onmessage = onMessage
    ws.onclose = e => { clearTimeout(t); open = false; if (!closed) { cleanup(); onClose?.(e.reason || ('connection closed (' + e.code + ')')) } reject(new Error(e.reason || 'closed ' + e.code)) }
  })

  function cleanup() {
    try { proc && (proc.onaudioprocess = null); proc?.disconnect(); src?.disconnect() } catch {}
    stream.getTracks().forEach(t => t.stop())
    stopPlayback()
    try { inCtx.close(); outCtx.close() } catch {}
  }
  return {
    live: true, model: cfg.model,
    get enabled() { return open },
    sendText(text) { sendJSON({ realtimeInput: { text } }) },
    stopSpeaking() { stopPlayback() },
    speak() {},
    stop() { if (closed) return; closed = true; open = false; try { sendJSON({ realtimeInput: { audioStreamEnd: true } }); ws.close(1000) } catch {} cleanup(); state('idle') },
  }
}
